import {requireUploadAccess} from './upload-auth.js';
const file=document.querySelector('#file'),button=document.querySelector('#upload'),progress=document.querySelector('#progress'),status=document.querySelector('#status'),preview=document.querySelector('#preview');
async function current(){const r=await fetch('/api/lecture-music?scope=city'),d=await r.json();if(d.url){preview.src=d.url;preview.hidden=false;}}
button.onclick=async()=>{const f=file.files[0];if(!f){status.textContent='请先选择音频或视频文件';return;}if(f.size>50*1024*1024){status.textContent='请选择 50MB 以内的文件';return;}button.disabled=true;try{await requireUploadAccess();progress.hidden=false;status.textContent='正在上传';const d=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/lecture-music?scope=city');x.timeout=180000;x.setRequestHeader('Content-Type','application/octet-stream');x.setRequestHeader('X-Music-Volume','.18');x.upload.onprogress=e=>{if(e.lengthComputable){progress.value=e.loaded/e.total*100;status.textContent='上传 '+Math.round(progress.value)+'%';}};x.onload=()=>{try{const d=JSON.parse(x.responseText);x.status<300?resolve(d):reject(Error(d.error));}catch(e){reject(e);}};x.onerror=x.ontimeout=()=>reject(Error('上传连接中断，请重试'));x.send(f);});status.textContent='上传完成，正在转换音频';progress.value=20;for(let i=0;i<150;i++){await new Promise(r=>setTimeout(r,2000));const r=await fetch('/api/lecture-music?scope=city&job='+encodeURIComponent(d.job));const j=await r.json();progress.value=j.progress||0;status.textContent=j.detail||'正在处理';if(j.status==='failed')throw Error(j.error);if(j.status==='complete'){progress.value=100;status.textContent='已保存。下次打开导览，苏州游览段将使用这段评弹。';await current();return;}}throw Error('处理时间较长，请稍后刷新查看');}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
current().catch(()=>{});
